'use strict';

const { CartItemNotFoundError } = require('./errors');
const {
  assertItemName,
  assertPrice,
  assertQuantity,
  assertMergedQuantity,
  assertDiscountPercent,
} = require('./validation');

/**
 * In-memory shopping cart. Each instance holds its own items and discount.
 * Every mutating method validates its arguments before changing state, so a
 * call that throws leaves the cart exactly as it was.
 */
class ShoppingCart {
  constructor() {
    /** @type {{ name: string, price: number, quantity: number }[]} */
    this.items = [];
    /** Discount in percent, from 0 to 100. */
    this.discount = 0;
  }

  /**
   * Adds a line item. If an item with the same name is already in the cart,
   * its quantity grows and the price from the first add is kept.
   * @param {string} name non-empty; compared exactly (case- and whitespace-sensitive)
   * @param {number} price finite, zero or greater
   * @param {number} quantity whole number, 1 or greater
   * @throws {TypeError|RangeError} on invalid arguments
   */
  addItem(name, price, quantity) {
    assertItemName(name);
    assertPrice(price);
    assertQuantity(quantity);

    const existing = this.items.find((item) => item.name === name);
    if (existing) {
      assertMergedQuantity(name, existing.quantity, quantity);
      existing.quantity += quantity;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  /**
   * Removes the whole line item with this exact name.
   * @param {string} name
   * @throws {CartItemNotFoundError} if no item has that name
   * @throws {TypeError|RangeError} if `name` is not a non-empty string
   */
  removeItem(name) {
    assertItemName(name);

    const index = this.items.findIndex((item) => item.name === name);
    if (index === -1) {
      throw new CartItemNotFoundError(name);
    }
    this.items.splice(index, 1);
  }

  /**
   * @returns {number} sum of price × quantity, minus the current discount
   */
  getTotal() {
    const subtotal = this.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    return subtotal - (subtotal * this.discount) / 100;
  }

  /**
   * Sets the discount, replacing any earlier one.
   * @param {number} percent finite, from 0 to 100 inclusive
   * @throws {TypeError|RangeError} on invalid input; the previous discount stays in place
   */
  applyDiscount(percent) {
    assertDiscountPercent(percent);
    this.discount = percent;
  }

  /**
   * @returns {number} number of distinct line items (not the sum of quantities)
   */
  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;

